#include "kstationControllerMidiControlRuntime.h"
#include "h8s/h8s.hpp"
#include <array>
#include <cstdio>
#include <fstream>
#include <memory>
#include <vector>
struct Ref: H8SEmulator {void history(int r,int w){lastread=r;lastwrite=w;}};
struct Event{uint64_t time;uint32_t addr;uint8_t value;bool write;};
static bool observed(uint32_t a){return (a>=0xba00&&a<0xd400)||(a>=0x18000&&a<0x1a000);}
struct RBus:H8SDevice{Ref&c;std::array<Event,16>e{};unsigned n=0;explicit RBus(Ref&x):c(x){}uint8_t read(uint32_t a)override{auto v=c.memory[a];if(observed(a))e[n++]={c.cycles,a,v,false};return v;}void write(uint32_t a,uint8_t v)override{if(observed(a))e[n++]={c.cycles,a,v,true};c.memory[a]=v;}};
struct NBus:kstation::ControllerResourceBus{std::array<Event,16>e{};unsigned n=0;bool mapped(uint32_t a)const override{return observed(a);}uint8_t read(uint32_t a)override{auto v=state_->memory[a];e[n++]={state_->cycles,a,v,false};return v;}void write(uint32_t a,uint8_t v)override{e[n++]={state_->cycles,a,v,true};state_->memory[a]=v;}};
int main(int argc,char**argv){if(argc!=2)return 77;std::ifstream f(argv[1],std::ios::binary);std::vector<uint8_t>rom{std::istreambuf_iterator<char>(f),{}};if(rom.size()!=49728)return 1;auto c=std::make_unique<Ref>();auto d=std::make_unique<kstation::ControllerDeviceState>();c->loadmem(rom.data(),unsigned(rom.size()),0);d->loadMemory(rom.data(),rom.size(),0);d->loadMemory(rom.data(),rom.size(),0x400000);RBus x(*c);NBus y;c->memmap(&x,0xba00,0x1a00);c->memmap(&x,0x18000,0x2000);d->attachBus(&y);kstation::ControllerInterruptRuntime irq;kstation::ControllerMidiControlRuntime ctl;if(!irq.bindVerifiedFirmware(*d,rom.data(),rom.size())||!ctl.bindVerifiedFirmware(*d,rom.data(),rom.size()))return 2;uint64_t graphs=0,phases=0,events=0,shorts=0,services=0;for(uint8_t number:{uint8_t(1),uint8_t(2),uint8_t(7),uint8_t(32),uint8_t(98),uint8_t(6),uint8_t(10),uint8_t(104),uint8_t(120),uint8_t(123),uint8_t(64)})for(uint8_t value:{uint8_t(0),uint8_t(1),uint8_t(24),uint8_t(32),uint8_t(44),uint8_t(63),uint8_t(64),uint8_t(68),uint8_t(127)})for(unsigned match=0;match<2;++match)for(uint8_t nrpn:{uint8_t(0),uint8_t(104),uint8_t(105),uint8_t(106),uint8_t(107),uint8_t(255)}){ctl.reset();irq.reset();irq.setMask(kstation::ControllerInterruptRuntime::Mask::Disabled);auto put=[&](uint32_t a,uint8_t v){c->memory[a]=d->memory[a]=v;};put(0xcad3,number);put(0xcad4,value);put(0xcad5,3);put(0xbb16,match?3:4);put(0xcc00,nrpn);put(0xcc01,16);put(0xcc02,16);put(0xbab4,0);put(0xd028,0);put(0xbfb8,0);put(0xcd7f,0);put(0xbb0e,0);for(uint32_t a=0xba5c;a<0xbb84;++a)if(a!=0xbab4&&a!=0xbb0e&&a!=0xbb16)put(a,uint8_t(a*13+number));for(uint32_t a:{0x785cu,0x5e64u,0x403cu,0x7760u,0x7644u,0x76d6u,0x7930u,0x4358u,0x571eu}){c->memory[a]=0x54;c->memory[a+1]=0x70;}c->pc=c->makepc(0x2e34);c->setSP(0xffff10);for(unsigned i=0;i<4;++i)c->memory[0xffff10+i]=uint8_t(0x7000u>>(8*(3-i)));c->reg32(4)=0xcad3;c->reg32(1)=0xca03;c->ccr=0x80;c->pending_irqs=d->pendingIrqs=0;c->pending_irqs_high=d->pendingIrqsHigh=0;c->interruptMode2=d->interruptMode2=false;c->cycles=d->cycles=100000;c->history(-1,-1);d->lastRead=d->lastWrite=-1;if(!ctl.start(3,0xcad3))return 3;for(unsigned k=0;ctl.active();++k){if(k>10000){std::fprintf(stderr,"hang pc=%x cc=%u val=%u\n",c->getPC(),number,value);return 4;}auto req=ctl.request();x.n=y.n=0;auto at=uint32_t(c->getPC());if(req.service!=kstation::ControllerMidiControlRuntime::Service::None){auto target=req.service==kstation::ControllerMidiControlRuntime::Service::Volume?0x403c:req.service==kstation::ControllerMidiControlRuntime::Service::RefreshModulation||req.service==kstation::ControllerMidiControlRuntime::Service::RefreshBreath?0x785c:req.service==kstation::ControllerMidiControlRuntime::Service::CommitModulation||req.service==kstation::ControllerMidiControlRuntime::Service::CommitBreath?0x5e64:req.service==kstation::ControllerMidiControlRuntime::Service::AllSoundOff?0x7760:req.service==kstation::ControllerMidiControlRuntime::Service::ReleaseVoices?0x7644:req.service==kstation::ControllerMidiControlRuntime::Service::ClearHeld?0x2b7a:req.service==kstation::ControllerMidiControlRuntime::Service::ReleaseSustain?0x76d6:req.service==kstation::ControllerMidiControlRuntime::Service::UpdateVoices?0x7930:req.service==kstation::ControllerMidiControlRuntime::Service::Display?0x4358:0x571e;if(at!=target){std::fprintf(stderr,"wrong request pc=%x expected=%x service=%u\n",at,target,unsigned(req.service));return 5;}c->step();d->cycles+=7;d->lastRead=-1;if(!ctl.completeService(req.service))return 6;++services;}else{auto budget=ctl.nextClocks(*d,irq);if(!budget){std::fprintf(stderr,"zero cost at %x cc=%u\n",at,number);return 7;}auto before=d->cycles;for(unsigned b=0;b<budget;++b){auto r=ctl.advanceBefore(*d,irq,b);if(r.clocks||d->cycles!=before||y.n)return 8;++shorts;}c->step();auto r=ctl.advanceBefore(*d,irq,budget);if(!r.clocks){std::fprintf(stderr,"runtime stalled at %x\n",at);return 9;}}if(c->cycles!=d->cycles||x.n!=y.n){std::fprintf(stderr,"phase pc=%x cc=%u val=%u nrpn=%u clocks=%llu/%llu io=%u/%u\n",at,number,value,nrpn,c->cycles,d->cycles,x.n,y.n);return 10;}for(unsigned i=0;i<x.n;++i)if(x.e[i].time!=y.e[i].time||x.e[i].addr!=y.e[i].addr||x.e[i].value!=y.e[i].value||x.e[i].write!=y.e[i].write){std::fprintf(stderr,"event pc=%x cc=%u idx=%u addr=%x/%x val=%x/%x time=%llu/%llu\n",at,number,i,x.e[i].addr,y.e[i].addr,x.e[i].value,y.e[i].value,x.e[i].time,y.e[i].time);return 11;}events+=x.n;++phases;}if(c->getPC()!=0x7000)return 12;for(uint32_t a=0x18000;a<0x1a000;++a)if(c->memory[a]!=d->memory[a])return 14;for(uint32_t a=0xba5c;a<0xd400;++a)if(c->memory[a]!=d->memory[a]){std::fprintf(stderr,"RAM %x cc=%u\n",a,number);return 13;}++graphs;}std::printf("{\"passed\":true,\"graphs\":%llu,\"phases\":%llu,\"events\":%llu,\"short_budgets\":%llu,\"external_services\":%llu}\n",(unsigned long long)graphs,(unsigned long long)phases,(unsigned long long)events,(unsigned long long)shorts,(unsigned long long)services);}
